sys_ui_action.script:
(function executeAction(current) {
    // Ensure the record has a patient assigned
    if (!current.u_patient_id) {
        gs.addErrorMessage("No patient assigned. Cannot create refill.");
        return;
    }

    // Create a new medication record
    var newMedication = new GlideRecord('u_medication');
    newMedication.initialize();

    // Copy fields from the current medication record
    newMedication.medication_name = current.u_medication_name;
    newMedication.patient_id = current.u_patient_id;
    newMedication.dosage = current.u_dosage;
    newMedication.frequency = current.u_frequency;
    newMedication.start_date = current.u_start_date;
    newMedication.end_date = current.u_end_date;

    // Optional: set refill_date to now (if field exists)
    // newMedication.refill_date = gs.nowDateTime();

    // Insert new record
    var newID = newMedication.insert();

    // Show success/failure message
    if (newID) {
        gs.addInfoMessage("Medication refill created successfully.");
    } else {
        gs.addErrorMessage("Failed to create medication refill.");
    }

})(current);
